    if (!hangs(y + 2) || !free(g, opts, x, y + 1, z)) return [];
    chain = true;
  }
  const w = writer(g, opts);
  if (chain) w.set(x, y + 1, z, ...B.chain("y"));
  w.set(x, y, z, ...B.lantern(true));
