27	export class Grid {
28	  /** @param {[number,number,number]} size */
29	  constructor(size, { dataVersion = DATA_VERSIONS["1.21.4"], entities = null } = {}) {
30	    this.size = [...size];
31	    this.dataVersion = dataVersion;
32	    this.entities = entities;                     // typed NBT list, passed through untouched
33	    /** @type {Map<string, {pos:number[], block:string, state?:Record<string,string>, nbt?:object}>} */
34	    this.cells = new Map();
35	  }
36	
37	  inBounds(x, y, z) {
38	    return x >= 0 && y >= 0 && z >= 0 && x < this.size[0] && y < this.size[1] && z < this.size[2];
39	  }
40	
41	  /** Set one block (state values become strings, as in NBT). Grows nothing: out of bounds throws. */
42	  set(x, y, z, block, state, nbt) {
43	    if (!this.inBounds(x, y, z)) throw new Error(`set out of bounds: ${x},${y},${z} (size ${this.size})`);
44	    const s = state && Object.keys(state).length
45	      ? Object.fromEntries(Object.entries(state).map(([k, v]) => [k, String(v)])) : undefined;
46	    this.cells.set(key(x, y, z), { pos: [x, y, z], block: ns(block), ...(s ? { state: s } : {}), ...(nbt ? { nbt } : {}) });
47	    return this;
